"], "Skilled help for home repairs and odd jobs. 5 years of experience.", 5]]$json$::jsonb;
  hash  text  := crypt('Demo@12345', gen_salt('bf', 6));   -- hashed once and reused
  v_id  uuid;
  n     int := 0;
begin
  if exists (select 1 from auth.users where email like 'demo.bulk%@labourchowk.demo') then
    raise notice 'Bulk sample workers already present - skipping.';
    return;
  end if;

  for w in select * from jsonb_array_elements(rows) loop
    n := n + 1;
    v_id := gen_random_uuid();
    insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
                            raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
                            confirmation_token, email_change, email_change_token_new, recovery_token)
    values ('00000000-0000-0000-0000-000000000000', v_id, 'authenticated', 'authenticated',
            format('demo.bulk%s@labourchowk.demo', lpad(n::text, 3, '0')), hash, now(),
            '{"provider":"email","providers":["email"]}',
            jsonb_build_object('role', 'worker', 'full_name', w->>1, 'phone', '96' || lpad((10000000 + n)::text, 8, '0'),
              'category_slug', w->>0, 'experience_years', (w->>2)::int, 'indicative_price', (w->>3)::numeric, 'pricing_unit', w->>4,
              'locality', w->>5, 'city', w->>6, 'latitude', (w->>7)::float8, 'longitude', (w->>8)::float8,
              'languages', w->9, 'skills', w->10, 'description', w->>11, 'service_radius_km', (w->>12)::int),
            now(), now(), '', '', '', '');
    insert into auth.identities (id, user_id, provider_id, provider, identity_data, last_sign_in_at, created_at, updated_at)
    values (gen_random_uuid(), v_id, v_id::text, 'email',
            jsonb_build_object('sub', v_id::text, 'email', format('demo.bulk%s@labourchowk.demo', lpad(n::text, 3, '0')), 'email_verified', true),
            now(), now(), now());
    -- the signup trigger created profiles / worker_profiles / skills; mark them as sample data
    update public.profiles set is_demo = true where id = v_id;
    update public.worker_profiles set is_demo = true where id = v_id;
  end loop;
  raise notice 'Inserted % bulk sample workers.', n;
end
$bulk$;
